import type {
	OptionalKind,
	PropertySignatureStructure,
	StatementStructures,
	WriterFunction,
} from 'ts-morph';
import { IndentationText, Project, QuoteKind, StructureKind, Writers } from 'ts-morph';

import type { ComponentRecord, ExportEntry, PropEvidence } from './types';
import type { Resolver } from './resolve';
import type { Inference } from './infer';

import { literalType, propertyKey } from './rules';
import { compare } from './naming';

export const BANNER =
	'// Generated by apps/discord-typegen from a Hermes decompile - DO NOT EDIT. Run `bun run generate-discord-types`.';

const MAX_SHARD_BYTES = 900_000;
const NO_PATH_GROUP = 'node-modules';

// Modules whose export map gets its own alias. The alias and every type it reaches go in one self-contained shard,
// so a consumer naming it compiles that shard alone instead of the whole build.
const NAMED_PATHS: ReadonlyMap<string, string> = new Map([
	['design/native.tsx', 'DesignBarrelComponents'],
]);
const NAMED_SHARD = 'barrels.gen.d.ts';

// Declaration files, so consumers' `skipLibCheck` skips the multi-megabyte output instead of checking it.
export const EXTENSION = '.gen.d.ts';

function specifier(file: string): string {
	return `./${file.replace(/\.d\.ts$/, '')}`;
}

/** Everything the emitter needs about the build. */
export type EmitInput = {
	build: string;
	components: ComponentRecord[];
	names: Map<ComponentRecord, string>;
	inference: Inference;
	resolve: Resolver;
	exports: ExportEntry[];
};

type Shard = { file: string; components: ComponentRecord[]; aliases: StatementStructures[] };

/**
 * @description Decides whether a prop must be passed. Only unguarded use with no default is strong enough.
 * @param evidence The prop's evidence.
 * @returns True when the component reads or calls the prop without ever checking it or defaulting it.
 */
export function isRequired(evidence: PropEvidence): boolean {
	const used = evidence.some((item) => item.kind === 'called' || item.kind === 'member');
	const optional = evidence.some(
		(item) =>
			item.kind === 'guarded' ||
			item.kind === 'default' ||
			item.kind === 'default-expression',
	);

	return used && !optional;
}

function createPrinter(): Project {
	return new Project({
		useInMemoryFileSystem: true,
		manipulationSettings: {
			indentationText: IndentationText.Tab,
			quoteKind: QuoteKind.Single,
		},
	});
}

function print(project: Project, file: string, statements: Array<string | StatementStructures>) {
	const source = project.createSourceFile(file, { statements }, { overwrite: true });
	const text = source.getFullText();

	project.removeSourceFile(source);

	return text;
}

function propsType(input: EmitInput, component: ComponentRecord): string | WriterFunction {
	const { inference, names } = input;
	const keys = [...component.props.keys()].sort();
	const properties: OptionalKind<PropertySignatureStructure>[] = keys.map((key) => {
		const evidence = component.props.get(key)!;
		const defaults = evidence.flatMap((item) => (item.kind === 'default' ? [item.value] : []));

		return {
			name: propertyKey(key),
			type: inference.typeOf(component, key).text,
			hasQuestionToken: !isRequired(evidence),
			docs:
				defaults.length > 0
					? [{ tags: [{ tagName: 'default', text: literalType(defaults[0]!) }] }]
					: [],
		};
	});
	const own = Writers.objectType({ properties });
	const rest = inference.restOf.get(component);

	if (!rest) {
		return own;
	}

	const base =
		rest.kind === 'host'
			? `React.ComponentProps<typeof RN.${rest.name}>`
			: `${names.get(rest.component)}Props`;
	const omitted = [...new Set([...keys, ...(inference.restOmits.get(component) ?? [])])].sort();

	if (omitted.length === 0) {
		return base;
	}

	const inherited = `Omit<${base}, ${omitted.map(literalType).join(' | ')}>`;

	return keys.length === 0 ? inherited : Writers.intersectionType(inherited, own);
}

function staticsType(input: EmitInput, component: ComponentRecord): string | undefined {
	const seen = new Set<string>();
	const members: string[] = [];

	for (const item of component.statics) {
		if (seen.has(item.name)) {
			continue;
		}

		seen.add(item.name);

		const resolved = item.target ? input.resolve(item.target) : undefined;
		const name =
			resolved?.kind === 'component' ? input.names.get(resolved.component) : undefined;
		let type = 'unknown';

		if (name) {
			type = `${name}Component`;
		} else if (resolved?.kind === 'host') {
			type = `typeof RN.${resolved.name}`;
		} else if (item.literal !== undefined) {
			type = item.literal === null ? 'null' : typeof item.literal;
		}

		members.push(`\t${propertyKey(item.name)}: ${type};`);
	}

	return members.length > 0 ? `{\n${members.join('\n')}\n}` : undefined;
}

function componentStatements(input: EmitInput, component: ComponentRecord): StatementStructures[] {
	const name = input.names.get(component)!;
	const statics = staticsType(input, component);
	const see = component.path ?? `module ${component.moduleId} (no source path)`;
	const exported = [...new Set(component.exportNames)].sort().join(', ') || 'none';
	const statements: StatementStructures[] = [
		{
			kind: StructureKind.TypeAlias,
			name: `${name}Props`,
			isExported: true,
			type: propsType(input, component),
			docs: [
				{
					description: `Props of \`${component.name}\` (${component.kind}). Exports: ${exported}.`,
					tags: [{ tagName: 'see', text: see }],
				},
			],
		},
	];

	if (statics) {
		statements.push({
			kind: StructureKind.TypeAlias,
			name: `${name}Statics`,
			isExported: true,
			type: statics,
		});
	}

	// An open component may read props the walk could not see, so rendering it accepts unseen keys too.
	const props = input.inference.open.has(component)
		? `${name}Props & Record<string, unknown>`
		: `${name}Props`;

	statements.push({
		kind: StructureKind.TypeAlias,
		name: `${name}Component`,
		isExported: true,
		type: statics
			? `React.ComponentType<${props}> & ${name}Statics`
			: `React.ComponentType<${props}>`,
	});

	return statements;
}

/** Other generated components a component's emitted types name. */
function referencedComponents(input: EmitInput, component: ComponentRecord): ComponentRecord[] {
	const refs: ComponentRecord[] = [];
	const rest = input.inference.restOf.get(component);

	if (rest?.kind === 'component') {
		refs.push(rest.component);
	}

	for (const key of component.props.keys()) {
		for (const ref of input.inference.typeOf(component, key).refs) {
			if (ref.kind === 'component') {
				refs.push(ref.component);
			}
		}
	}

	for (const item of component.statics) {
		const resolved = item.target ? input.resolve(item.target) : undefined;

		if (resolved?.kind === 'component' && input.names.has(resolved.component)) {
			refs.push(resolved.component);
		}
	}

	return refs;
}

function groupOf(component: ComponentRecord): string {
	const root = component.path?.split('/').find((segment) => segment !== '..' && segment !== '.');

	return root ? root.replace(/[^\w-]/g, '_') : NO_PATH_GROUP;
}

function header(imports: Map<string, Set<string>>): Array<string | StatementStructures> {
	const statements: Array<string | StatementStructures> = [
		BANNER,
		{
			kind: StructureKind.ImportDeclaration,
			isTypeOnly: true,
			// Namespace imports: every generated name ends in Props, Statics or Component, so these never collide.
			namespaceImport: 'React',
			moduleSpecifier: 'react',
		},
		{
			kind: StructureKind.ImportDeclaration,
			isTypeOnly: true,
			namespaceImport: 'RN',
			moduleSpecifier: 'react-native',
		},
	];

	for (const [file, names] of [...imports].sort(([a], [b]) => compare(a, b))) {
		statements.push({
			kind: StructureKind.ImportDeclaration,
			isTypeOnly: true,
			namedImports: [...names].sort(),
			moduleSpecifier: specifier(file),
		});
	}

	return statements;
}

// One alias per named path: its export map, as `exportName: TypeComponent` members.
function namedAliases(input: EmitInput): StatementStructures[] {
	const maps = new Map<string, string[]>();

	for (const { path, exportName, component } of input.exports) {
		if (!NAMED_PATHS.has(path)) {
			continue;
		}

		const line = `${propertyKey(exportName)}: ${input.names.get(component)}Component;`;

		maps.set(path, [...(maps.get(path) ?? []), line]);
	}

	return [...maps].map(([path, lines]) => ({
		kind: StructureKind.TypeAlias,
		name: NAMED_PATHS.get(path)!,
		isExported: true,
		type: `{\n\t${lines.join('\n\t')}\n}`,
		docs: [`Exported components of \`${path}\` in Discord ${input.build}.`],
	}));
}

// The named paths' components and every component their types reference, transitively.
function namedClosure(input: EmitInput): Set<ComponentRecord> {
	const closure = new Set<ComponentRecord>();
	const pending = input.exports
		.filter(({ path }) => NAMED_PATHS.has(path))
		.map(({ component }) => component);

	for (let component = pending.pop(); component; component = pending.pop()) {
		if (closure.has(component)) {
			continue;
		}

		closure.add(component);
		pending.push(...referencedComponents(input, component));
	}

	return closure;
}

function planShards(input: EmitInput, project: Project): Shard[] {
	const closure = namedClosure(input);
	const groups = new Map<string, ComponentRecord[]>();
	const shards: Shard[] = [];

	if (closure.size > 0) {
		shards.push({
			file: NAMED_SHARD,
			components: input.components.filter((component) => closure.has(component)),
			aliases: namedAliases(input),
		});
	}

	for (const component of input.components) {
		if (closure.has(component)) {
			continue;
		}

		const group = groupOf(component);

		groups.set(group, [...(groups.get(group) ?? []), component]);
	}

	for (const [group, components] of [...groups].sort(([a], [b]) => compare(a, b))) {
		const body = components.flatMap((component) => componentStatements(input, component));
		const size = print(project, '/size.ts', body).length;
		const parts = Math.max(1, Math.ceil(size / MAX_SHARD_BYTES));
		const per = Math.ceil(components.length / parts);

		for (let i = 0; i < parts; i++) {
			shards.push({
				file: parts === 1 ? `${group}${EXTENSION}` : `${group}-${i + 1}${EXTENSION}`,
				components: components.slice(i * per, (i + 1) * per),
				aliases: [],
			});
		}
	}

	return shards;
}

/**
 * @description Prints the generated type files: a self-contained shard for the named paths, one shard per
 * source-path root (split when over ~1 MB) and an index with the lookup maps.
 * @param input The build, its components, their names and inferred types.
 * @returns File name (relative to the output directory) to file text.
 */
export function emit(input: EmitInput): Map<string, string> {
	const project = createPrinter();
	const shards = planShards(input, project);
	const shardOf = new Map<ComponentRecord, string>();
	const files = new Map<string, string>();

	for (const shard of shards) {
		for (const component of shard.components) shardOf.set(component, shard.file);
	}

	for (const shard of shards) {
		const imports = new Map<string, Set<string>>();

		for (const component of shard.components) {
			for (const ref of referencedComponents(input, component)) {
				const file = shardOf.get(ref);

				if (!file || file === shard.file) {
					continue;
				}

				const name = input.names.get(ref)!;

				imports.set(
					file,
					(imports.get(file) ?? new Set()).add(`${name}Props`).add(`${name}Component`),
				);
			}
		}

		const body = shard.components.flatMap((component) => componentStatements(input, component));

		files.set(
			shard.file,
			print(project, `/${shard.file}`, [...header(imports), ...shard.aliases, ...body]),
		);
	}

	files.set(`index${EXTENSION}`, printIndex(input, project, shards, shardOf));

	return files;
}

function printIndex(
	input: EmitInput,
	project: Project,
	shards: Shard[],
	shardOf: Map<ComponentRecord, string>,
): string {
	const imports = new Map<string, Set<string>>();
	const byPath = new Map<string, Map<string, string>>();
	const byName = new Map<string, Set<string>>();

	for (const { path, exportName, component } of input.exports) {
		const type = `${input.names.get(component)}Component`;
		const file = shardOf.get(component)!;
		const key = exportName === 'default' ? component.name : exportName;

		imports.set(file, (imports.get(file) ?? new Set()).add(type));
		byPath.set(path, (byPath.get(path) ?? new Map()).set(exportName, type));
		byName.set(key, (byName.get(key) ?? new Set()).add(type));
	}

	const pathMembers = [...byPath].map(([path, members]) => {
		const alias = NAMED_PATHS.get(path);

		if (alias) {
			imports.set(NAMED_SHARD, (imports.get(NAMED_SHARD) ?? new Set()).add(alias));

			return `\t${literalType(path)}: ${alias};`;
		}

		const lines = [...members].map(([name, type]) => `\t\t${propertyKey(name)}: ${type};`);

		return `\t${literalType(path)}: {\n${lines.join('\n')}\n\t};`;
	});
	const nameMembers = [...byName]
		.filter(([, types]) => types.size === 1)
		.sort(([a], [b]) => compare(a, b))
		.map(([name, types]) => `\t${propertyKey(name)}: ${[...types][0]};`);

	return print(project, `/index${EXTENSION}`, [
		...header(imports),
		...shards.map((shard) => `export * from '${specifier(shard.file)}';`),
		{
			kind: StructureKind.TypeAlias,
			name: 'DiscordBuild',
			isExported: true,
			type: literalType(input.build),
			docs: ['The decompiled Discord build these types were generated from.'],
		},
		{
			kind: StructureKind.TypeAlias,
			name: 'DiscordComponentsByPath',
			isExported: true,
			type: `{\n${pathMembers.join('\n')}\n}`,
			docs: [
				`Exported components of Discord ${input.build}, keyed by source path, then export name.`,
			],
		},
		{
			kind: StructureKind.TypeAlias,
			name: 'DiscordComponentsByName',
			isExported: true,
			type: `{\n${nameMembers.join('\n')}\n}`,
			docs: [
				`Exported components of Discord ${input.build} whose export name is unique in the build.`,
			],
		},
	]);
}

export default { BANNER, EXTENSION, isRequired, emit };
